package com.rulecraft.decisionops.deployment.api;
import com.rulecraft.decisionops.deployment.RuntimeDeploymentService;import com.rulecraft.decisionops.deployment.RuntimeDeploymentService.*;import com.rulecraft.decisionops.identity.security.CurrentUser;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/runtime-sandbox")
public class RuntimeDeploymentController {private final RuntimeDeploymentService service;public RuntimeDeploymentController(RuntimeDeploymentService service){this.service=service;}@GetMapping SandboxView sandbox(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication auth){return service.sandbox(CurrentUser.require(auth),projectId,serviceId);}@PostMapping("/deployments")@ResponseStatus(HttpStatus.CREATED)DeploymentView deploy(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody DeployCommand command,Authentication auth){return service.deploy(CurrentUser.require(auth),projectId,serviceId,command);}@GetMapping("/deployments/{deploymentId}")DeploymentDetail detail(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID deploymentId,Authentication auth){return service.detail(CurrentUser.require(auth),projectId,serviceId,deploymentId);}@PostMapping("/deployments/{deploymentId}/retire")DeploymentView retire(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID deploymentId,@RequestBody StateCommand command,Authentication auth){return service.retire(CurrentUser.require(auth),projectId,serviceId,deploymentId,command);}@PostMapping("/deployments/{deploymentId}/rollback")DeploymentView rollback(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID deploymentId,@RequestBody StateCommand command,Authentication auth){return service.rollback(CurrentUser.require(auth),projectId,serviceId,deploymentId,command);}@PostMapping("/evaluations")EvaluationView evaluate(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody EvaluationCommand command,Authentication auth){return service.evaluate(CurrentUser.require(auth),projectId,serviceId,command);}}
